import itertools, json
jobs='ABCDE'
slot=[[10,7,11,4,4],[3,1,1,4,8],[5,4,5,6,2],[3,3,7,1,11],[10,9,10,1,9]]
transfer=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
idx={j:i for i,j in enumerate(jobs)}
def nominal(p):
    return sum(slot[idx[j]][i] for i,j in enumerate(p))+sum(transfer[idx[a]][idx[b]] for a,b in zip(p,p[1:]))
def incident(p,s):
    pos={j:p.index(j)+1 for j in jobs}
    if pos['A']>=pos['D']: return None
    if s=='rain':
        if pos['C']==5 or pos['A']==1: return None
        return nominal(p)+8*max(0,pos['E']-1)
    if s=='road':
        if pos['B']==1 or pos['C']==2: return None
        return nominal(p)+5*max(0,pos['D']-3)
    if pos['D']==5 or pos['B']==5: return None
    return nominal(p)+5*max(0,pos['E']-2)
perms=[''.join(p) for p in itertools.permutations(jobs) if p.index('A')<p.index('D')]
results=[]
for p in perms:
    options=[(p,0)]
    for i,j in itertools.combinations(range(5),2):
        q=list(p);q[i],q[j]=q[j],q[i]
        options.append((''.join(q),1))
    best={}
    for s in ['rain','road','lift']:
        legal=[(incident(q,s)+ex,q) for q,ex in options if incident(q,s) is not None]
        if not legal: break
        best[s]=min(legal)
    if len(best)==3:
        results.append((nominal(p)+max(v[0] for v in best.values()),p,best))
results.sort()
score,p,best=results[0]
answer={'roster':p,'score':score,'repairs':{s:v[1] for s,v in best.items()},'repair_costs':{s:v[0] for s,v in best.items()},'feasible_count':len(results),'next_score':min(r[0] for r in results if r[0]>score)}
# Independent exhaustive pairwise reachability and cost calculation.
values=[]
for pub in itertools.permutations(range(5)):
    if pub.index(0)>pub.index(3): continue
    base=sum(slot[j][k] for k,j in enumerate(pub))+sum(transfer[pub[k]][pub[k+1]] for k in range(4))
    mins=[float('inf')]*3
    for final in itertools.permutations(range(5)):
        dif=sum(a!=b for a,b in zip(pub,final))
        if dif not in (0,2) or final.index(0)>final.index(3): continue
        c=sum(slot[final[k]][k] for k in range(5))+sum(transfer[final[k]][final[k+1]] for k in range(4))+(dif==2)
        a,b,cc,d,e=[final.index(j) for j in range(5)]
        if cc!=4 and a!=0: mins[0]=min(mins[0],c+8*e)
        if b!=0 and cc!=1: mins[1]=min(mins[1],c+5*max(0,d-2))
        if d!=4 and b!=4: mins[2]=min(mins[2],c+5*max(0,e-1))
    if max(mins)<float('inf'): values.append((base+max(mins),''.join(jobs[j] for j in pub)))
assert len(values)==answer['feasible_count']
assert min(v[0] for v in values)==score
assert min(v[0] for v in values if v[0]>score)==answer['next_score']
assert (score,p) in values
print(json.dumps(answer))
print('Verified with two exhaustive implementations; published nominal:',nominal(p))

